// v0.3.0: the source at a revision, and the optional content delete. Each plant is a request that
// must be refused; where the package refuses it, the test also checks that the adapter never ran.

import { describe, expect, it, vi } from "vitest";
import { RefusedError } from "../src/adapter.js";
import { createSiteClient, SiteApiError } from "../src/client.js";
import { memoryAdapter } from "../src/testing.js";
import { KEY, ORIGIN, req, site } from "./helpers.js";

function client(adapter = memoryAdapter()) {
  const s = site(adapter);
  return { ...s, client: createSiteClient({ baseUrl: ORIGIN, key: KEY, fetch: s.fetch }) };
}

async function seeded(adapter = memoryAdapter()) {
  const c = client(adapter);
  const first = await c.client.saveDraft("first-post", { source: "# First\n", expectedVersion: null, changeId: "c1" });
  const second = await c.client.saveDraft("first-post", { source: "# First, edited\n", expectedVersion: first.version, changeId: "c2" });
  return { ...c, first, second };
}

describe("the source at a revision", () => {
  it("opens each revision in the list with the source it had", async () => {
    const { client: c, first, second } = await seeded();
    const list = await c.revisions("first-post");
    expect(list.items.map((r) => r.version)).toEqual([second.version, first.version]);
    expect(await c.revision("first-post", first.version)).toEqual({ id: "first-post", version: first.version, source: "# First\n" });
    expect((await c.revision("first-post", second.version)).source).toBe("# First, edited\n");
  });

  it("answers 404 for a version or an item the site does not hold", async () => {
    const { client: c } = await seeded();
    await expect(c.revision("first-post", "no-such-version")).rejects.toMatchObject({ status: 404 });
    await expect(c.revision("no-such-post", "v1")).rejects.toMatchObject({ status: 404 });
  });

  it("refuses an id or a version that could not be one, before the site sees it", async () => {
    const adapter = memoryAdapter();
    const spy = vi.spyOn(adapter.content, "revisionSource");
    const { api } = site(adapter);
    expect((await api.handle(req("/api/carrel/v1/content/..%2Fx/revisions/v1"))).status).toBe(400);
    expect((await api.handle(req(`/api/carrel/v1/content/a/revisions/${"v".repeat(201)}`))).status).toBe(400);
    expect((await api.handle(req("/api/carrel/v1/content/a/revisions/%E0%A4%A"))).status).toBe(400);
    expect(spy).not.toHaveBeenCalled();
  });

  it("is refused without the key", async () => {
    const { api } = site();
    expect((await api.handle(req("/api/carrel/v1/content/a/revisions/v1", { key: null }))).status).toBe(401);
  });
});

describe("content delete", () => {
  it("deletes an item at the version the caller saw, and reports the change id", async () => {
    const { client: c, adapter, second } = await seeded();
    expect(await c.delete("first-post", { expectedVersion: second.version, changeId: "c3" })).toEqual({ id: "first-post", deleted: true, changeId: "c3" });
    expect(adapter.deletedContent).toEqual(["first-post"]);
    await expect(c.get("first-post")).rejects.toMatchObject({ status: 404 });
  });

  it("advertises the delete in meta, and not on a site without one", async () => {
    expect((await client().client.meta()).capabilities.contentDelete).toBe(true);
    expect((await client(memoryAdapter({ contentDelete: false })).client.meta()).capabilities.contentDelete).toBeUndefined();
  });

  it("PLANT: refuses a stale version with 409 and the current version, and deletes nothing", async () => {
    const { client: c, adapter, first, second } = await seeded();
    const error = await c.delete("first-post", { expectedVersion: first.version, changeId: "c3" }).catch((e) => e);
    expect(error).toBeInstanceOf(SiteApiError);
    expect(error.status).toBe(409);
    expect(error.body).toMatchObject({ error: "version-conflict", currentVersion: second.version });
    expect(adapter.store.has("first-post")).toBe(true);
    expect(adapter.deletedContent).toEqual([]);
  });

  it("PLANT: answers 404 for an item the site does not hold", async () => {
    const { client: c, adapter } = client();
    const error = await c.delete("no-such-post", { expectedVersion: "v1", changeId: "c3" }).catch((e) => e);
    expect(error.status).toBe(404);
    expect(error.body.error).toBe("not-found");
    expect(adapter.deletedContent).toEqual([]);
  });

  it("PLANT: answers 501 on a site whose adapter has no delete, and the item stays", async () => {
    const { client: c, adapter, second } = await seeded(memoryAdapter({ contentDelete: false }));
    const error = await c.delete("first-post", { expectedVersion: second.version, changeId: "c3" }).catch((e) => e);
    expect(error.status).toBe(501);
    expect(error.body.error).toBe("not-implemented");
    expect(adapter.store.has("first-post")).toBe(true);
  });

  it("PLANT: the site's own refusal comes back as 422 refused with its words, and the item stays", async () => {
    const adapter = memoryAdapter();
    const { client: c, second } = await seeded(adapter);
    adapter.content.delete = async () => {
      throw new RefusedError("The site keeps this page.");
    };
    const error = await c.delete("first-post", { expectedVersion: second.version, changeId: "c3" }).catch((e) => e);
    expect(error.status).toBe(422);
    expect(error.body).toMatchObject({ error: "refused", message: "The site keeps this page." });
    expect(adapter.store.has("first-post")).toBe(true);
  });

  it("PLANT: refused without the key or with a wrong one, before the adapter runs", async () => {
    const adapter = memoryAdapter();
    const spy = vi.fn(adapter.content.delete!);
    adapter.content.delete = spy;
    const { api } = site(adapter);
    const path = "/api/carrel/v1/content/first-post?expectedVersion=v1&changeId=c1";
    for (const key of [null, `${KEY}x`]) {
      expect((await api.handle(req(path, { method: "DELETE", key }))).status).toBe(401);
    }
    expect(spy).not.toHaveBeenCalled();
  });

  it("PLANT: refuses a delete with no expectedVersion or change id, or a bad id, before the adapter runs", async () => {
    const adapter = memoryAdapter();
    const spy = vi.fn(adapter.content.delete!);
    adapter.content.delete = spy;
    const { api } = site(adapter);
    for (const path of [
      "/api/carrel/v1/content/first-post",
      "/api/carrel/v1/content/first-post?expectedVersion=v1",
      "/api/carrel/v1/content/first-post?changeId=c1",
      "/api/carrel/v1/content/first-post?expectedVersion=v1&changeId=has%20spaces",
      "/api/carrel/v1/content/..%2Fsecrets?expectedVersion=v1&changeId=c1",
    ]) {
      expect((await api.handle(req(path, { method: "DELETE" }))).status, path).toBe(400);
    }
    expect(spy).not.toHaveBeenCalled();
  });
});

test/media.test.ts.source:
// The media group (v0.2.0): the round trip through the client, and the plants. Each plant is a
// request that must be refused; where the package refuses it, the test also checks that the
// adapter never ran, so a refusal cannot come from the site's own code by accident.

import { describe, expect, it, vi } from "vitest";
import { createSiteClient, SiteApiError } from "../src/client.js";
import { memoryAdapter } from "../src/testing.js";
import { KEY, ORIGIN, req, site } from "./helpers.js";

const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);
const JPEG = Uint8Array.from([0xff, 0xd8, 0xff, 0xe0, 0, 16, 0x4a, 0x46, 0x49, 0x46]);

function spied(options: Parameters<typeof memoryAdapter>[0] = {}) {
  const adapter = memoryAdapter(options);
  const calls = vi.fn();
  const media = adapter.media!;
  for (const name of ["list", "get", "upload", "delete"] as const) {
    const fn = media[name] as (...a: unknown[]) => unknown;
    (media as unknown as Record<string, unknown>)[name] = (...args: unknown[]) => {
      calls(name);
      return fn(...args);
    };
  }
  return { adapter, calls };
}

function client(adapter = memoryAdapter()) {
  const s = site(adapter);
  return { ...s, client: createSiteClient({ baseUrl: ORIGIN, key: KEY, fetch: s.fetch }) };
}

function upload(bytes: Uint8Array, type: string, filename = "photo.png", headers: Record<string, string> = {}) {
  return req(`/api/carrel/v1/media?filename=${encodeURIComponent(filename)}&changeId=c1`, {
    method: "POST",
    body: new Blob([bytes as Uint8Array<ArrayBuffer>]),
    headers: { "content-type": type, ...headers },
  });
}

describe("media round trip", () => {
  it("uploads, lists, searches, reads and deletes a file through the client", async () => {
    const { client: c, adapter } = client();
    const item = await c.media.upload({ bytes: PNG, contentType: "image/png", filename: "Paluxy River.png", alt: "The river", changeId: "c1" });
    expect(item).toMatchObject({ url: `/media/${item.id}`, filename: "Paluxy River.png", contentType: "image/png", bytes: PNG.byteLength, alt: "The river", deletable: true });
    expect(adapter.mediaStore.get(item.id)?.bytes).toEqual(PNG);

    await c.media.upload({ bytes: JPEG, contentType: "image/jpeg", filename: "tracks.jpg", changeId: "c2" });
    expect((await c.media.list()).items.map((i) => i.filename)).toEqual(["tracks.jpg", "Paluxy River.png"]);
    expect((await c.media.list({ q: "river" })).items.map((i) => i.id)).toEqual([item.id]);
    expect(await c.media.list({ limit: 1 })).toMatchObject({ items: [{ filename: "tracks.jpg" }], nextCursor: "1" });

    expect(await c.media.get(item.id)).toMatchObject({ id: item.id, usedBy: [] });
    expect(await c.media.delete(item.id, "c3")).toEqual({ id: item.id, deleted: true, changeId: "c3" });
    expect(adapter.deleted).toEqual([item.id]);
    await expect(c.media.get(item.id)).rejects.toMatchObject({ status: 404 });
  });

  it("strips a type's parameters and accepts the site's type in any case", async () => {
    const { api } = site();
    const response = await api.handle(upload(PNG, "Image/PNG; charset=binary"));
    expect(response.status).toBe(201);
    expect(await response.json()).toMatchObject({ contentType: "image/png" });
  });
});

describe("PLANT: deleting a file a post uses", () => {
  it("is refused with the post named, and deletes once the post stops using it", async () => {
    const { client: c, adapter } = client();
    const item = await c.media.upload({ bytes: PNG, contentType: "image/png", filename: "cover.png", changeId: "c1" });
    const saved = await adapter.content.saveDraft("river-post", {
      source: `---\ntitle: The river\n---\nIntro.\n\n![The river](${item.url})\n`,
      expectedVersion: null,
      changeId: "c2",
    });

    expect(await c.media.get(item.id)).toMatchObject({ usedBy: [{ type: "post", id: "river-post", title: "The river", detail: "line 6" }] });
    const refused = await c.media.delete(item.id, "c3").catch((e: unknown) => e);
    expect(refused).toBeInstanceOf(SiteApiError);
    const error = refused as SiteApiError;
    expect(error.status).toBe(422);
    expect(error.body).toMatchObject({ error: "refused", usedBy: [{ id: "river-post", title: "The river" }] });
    expect(error.body!.message).toContain("The river (line 6)");
    expect(adapter.mediaStore.has(item.id)).toBe(true);
    expect(adapter.deleted).toEqual([]);

    await adapter.content.saveDraft("river-post", { source: "---\ntitle: The river\n---\nIntro.\n", expectedVersion: saved.version, changeId: "c4" });
    expect(await c.media.delete(item.id, { changeId: "c5" })).toMatchObject({ deleted: true, changeId: "c5" });
  });

  it("names every post that uses it", async () => {
    const { client: c, adapter } = client();
    const item = await c.media.upload({ bytes: PNG, contentType: "image/png", filename: "shared.png", changeId: "c1" });
    for (const id of ["one", "two"]) await adapter.content.saveDraft(id, { source: `# Post ${id}\n\n![](${item.url})\n`, expectedVersion: null, changeId: `s-${id}` });
    const error = (await c.media.delete(item.id, "c2").catch((e: unknown) => e)) as SiteApiError;
    expect(error.body?.usedBy?.map((u) => u.id)).toEqual(["one", "two"]);
  });
});

describe("PLANT: an upload the site does not accept", () => {
  it("refuses a file over the site's limit, and never hands it to the site", async () => {
    const { adapter, calls } = spied({ media: { maxBytes: 100, types: ["image/png"] } });
    const { api } = site(adapter);
    const big = new Uint8Array(101);
    big.set(PNG.subarray(0, 8));
    const response = await api.handle(upload(big, "image/png"));
    expect(response.status).toBe(413);
    expect(await response.json()).toMatchObject({ error: "too-large" });
    expect(calls).not.toHaveBeenCalled();
    expect(adapter.mediaStore.size).toBe(0);
  });

  it("refuses a file that declares a length over the limit, before reading it", async () => {
    const { adapter, calls } = spied({ media: { maxBytes: 100, types: ["image/png"] } });
    const { api } = site(adapter);
    let pulled = 0;
    const body = new ReadableStream<Uint8Array>({
      pull(controller) {
        pulled += 1;
        controller.enqueue(PNG);
        controller.close();
      },
      // No read-ahead: a pull happens only when someone reads.
    }, { highWaterMark: 0 });
    const request = new Request(`${ORIGIN}/api/carrel/v1/media?filename=a.png&changeId=c1`, {
      method: "POST",
      body,
      headers: { authorization: `Bearer ${KEY}`, "content-type": "image/png", "content-length": "1000000" },
      duplex: "half",
    } as RequestInit);
    const response = await api.handle(request);
    expect(response.status).toBe(413);
    expect(pulled).toBe(0);
    expect(calls).not.toHaveBeenCalled();
  });

  it("refuses a type the site did not declare, and never hands it to the site", async () => {
    const { adapter, calls } = spied({ media: { maxBytes: 1000, types: ["image/png"] } });
    const { api } = site(adapter);
    for (const [type, bytes] of [
      ["text/html", new TextEncoder().encode("<script>alert(1)</script>")],
      ["image/svg+xml", new TextEncoder().encode("<svg xmlns='http://www.w3.org/2000/svg'/>")],
      ["image/jpeg", JPEG],
      ["", PNG],
    ] as const) {
      const response = await api.handle(upload(bytes, type));
      expect(response.status, type).toBe(400);
      expect(await response.json(), type).toMatchObject({ error: "invalid" });
    }
    expect(calls).not.toHaveBeenCalled();
  });

  it("refuses bytes that are not the type they were sent as", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter);
    for (const [type, bytes] of [
      ["image/png", JPEG],
      ["image/jpeg", PNG],
      ["image/png", new TextEncoder().encode("<html>not an image</html>")],
      ["image/svg+xml", new TextEncoder().encode("plain text, no svg element")],
      ["image/gif", PNG],
      ["image/webp", PNG],
    ] as const) {
      const response = await api.handle(upload(bytes, type));
      expect(response.status, `${type} carrying other bytes`).toBe(400);
      expect((await response.json()).message).toContain("do not match");
    }
    expect(calls).not.toHaveBeenCalled();
  });

  it("refuses an empty file, and a file name carrying a path", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter);
    expect((await api.handle(upload(new Uint8Array(0), "image/png"))).status).toBe(400);
    for (const name of ["../evil.png", "dir/evil.png", "dir\\evil.png"]) {
      expect((await api.handle(upload(PNG, "image/png", name))).status, name).toBe(400);
    }
    expect(calls).not.toHaveBeenCalled();
  });
});

describe("PLANT: a media id that climbs out", () => {
  for (const id of ["../secret", "a/../../b", "/etc/passwd", "a//b", ".hidden", "%00"]) {
    it(`refuses ${JSON.stringify(id)} for get and delete, before the site sees it`, async () => {
      const { adapter, calls } = spied();
      const { api } = site(adapter);
      const path = `/api/carrel/v1/media/${encodeURIComponent(id)}`;
      expect((await api.handle(req(path))).status).toBe(400);
      expect((await api.handle(req(`${path}?changeId=c1`, { method: "DELETE" }))).status).toBe(400);
      expect(calls).not.toHaveBeenCalled();
    });
  }

  it("refuses a delete with no changeId", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter);
    expect((await api.handle(req("/api/carrel/v1/media/uploads%2F1-a.png", { method: "DELETE" }))).status).toBe(400);
    expect(calls).not.toHaveBeenCalled();
  });
});

describe("PLANT: a site answering outside the media contract", () => {
  it("is reported as a site failure, and its answer is never passed on", async () => {
    const adapter = memoryAdapter();
    adapter.media!.list = async () => ({ items: [{ id: "../x", url: "javascript:alert(1)" }], nextCursor: null }) as never;
    const { api, logs } = site(adapter);
    const response = await api.handle(req("/api/carrel/v1/media"));
    expect(response.status).toBe(500);
    expect(await response.json()).toEqual({ error: "internal", message: "The site answered outside the contract." });
    expect(logs).toContainEqual(expect.objectContaining({ siteApi: "contract-breach" }));
  });
});

test/media-writes.test.ts.source:
// Media writes (v0.4.0): alt, tags, trash, restore, empty trash and the bulk route. Each write is
// versioned; each refusal is checked together with the fact that nothing changed.

import { describe, expect, it } from "vitest";
import { createSiteClient, SiteApiError } from "../src/client.js";
import { memoryAdapter } from "../src/testing.js";
import { KEY, ORIGIN, body, req, site } from "./helpers.js";

const PNG = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

function setup(options: Parameters<typeof memoryAdapter>[0] = {}) {
  const s = site(memoryAdapter(options));
  const client = createSiteClient({ baseUrl: ORIGIN, key: KEY, fetch: s.fetch });
  const add = (filename: string) => client.media.upload({ bytes: PNG, contentType: "image/png", filename, alt: "first", changeId: `up-${filename.replace(/[^A-Za-z0-9]/g, "")}` });
  return { ...s, client, add };
}

async function refused(promise: Promise<unknown>) {
  const error = await promise.then(
    () => null,
    (e: unknown) => e,
  );
  expect(error).toBeInstanceOf(SiteApiError);
  return error as SiteApiError;
}

describe("alt text", () => {
  it("changes the alt, moves the version, and refuses the old version after", async () => {
    const { client, add, adapter } = setup();
    const file = await add("a.png");
    expect(file.version).toBeTruthy();
    const done = await client.media.setAlt(file.id, { alt: "A river at dusk", expectedVersion: file.version!, changeId: "c1" });
    expect(done).toEqual({ id: file.id, version: expect.any(String), changeId: "c1" });
    expect(done.version).not.toBe(file.version);
    expect(adapter.mediaStore.get(file.id)?.item.alt).toBe("A river at dusk");
    expect((await client.media.get(file.id)).version).toBe(done.version);

    const stale = await refused(client.media.setAlt(file.id, { alt: "Lost update", expectedVersion: file.version!, changeId: "c2" }));
    expect(stale.status).toBe(409);
    expect(stale.body).toMatchObject({ error: "version-conflict", currentVersion: done.version });
    expect(adapter.mediaStore.get(file.id)?.item.alt).toBe("A river at dusk");
  });

  it("answers 404 for a missing file and 400 for a malformed body", async () => {
    const { client, fetch } = setup();
    expect((await refused(client.media.setAlt("nope.png", { alt: "x", expectedVersion: "m1", changeId: "c" }))).status).toBe(404);
    const bad = await fetch(req("/api/carrel/v1/media/nope.png/alt", { method: "PUT", ...body({ alt: 7, expectedVersion: "m1", changeId: "c" }) }));
    expect(bad.status).toBe(400);
  });
});

describe("tags", () => {
  it("stores the set sorted and without duplicates, and filters the list by tag", async () => {
    const { client, add } = setup();
    const a = await add("a.png");
    const b = await add("b.png");
    const done = await client.media.setTags(a.id, { tags: ["river", "dusk", "river"], expectedVersion: a.version!, changeId: "c1" });
    expect((await client.media.get(a.id)).tags).toEqual(["dusk", "river"]);
    expect((await client.media.list({ tag: "dusk" })).items.map((i) => i.id)).toEqual([a.id]);
    expect((await client.media.list({ tag: "nothing" })).items).toEqual([]);
    expect(done.version).not.toBe(a.version);
    expect((await client.media.get(b.id)).tags).toEqual([]);
  });

  it("refuses a stale version, a badly spelled tag and more than 12 tags, changing nothing", async () => {
    const { client, add, adapter, fetch } = setup();
    const a = await add("a.png");
    await client.media.setTags(a.id, { tags: ["one"], expectedVersion: a.version!, changeId: "c1" });
    expect((await refused(client.media.setTags(a.id, { tags: ["two"], expectedVersion: a.version!, changeId: "c2" }))).status).toBe(409);
    expect(adapter.mediaStore.get(a.id)?.item.tags).toEqual(["one"]);
    const current = adapter.mediaStore.get(a.id)!.item.version!;
    for (const tags of [["Upper Case"], Array.from({ length: 13 }, (_, i) => `t${i}`)]) {
      const response = await fetch(req(`/api/carrel/v1/media/${encodeURIComponent(a.id)}/tags`, { method: "PUT", ...body({ tags, expectedVersion: current, changeId: "c3" }) }));
      expect(response.status).toBe(400);
    }
    expect(adapter.mediaStore.get(a.id)?.item.tags).toEqual(["one"]);
  });
});

describe("trash, restore and empty", () => {
  it("hides a trashed file from the list, shows it in the trash, and brings it back on restore", async () => {
    const { client, add, adapter } = setup();
    const a = await add("a.png");
    const trashed = await client.media.trash(a.id, { expectedVersion: a.version!, changeId: "c1" });
    expect((await client.media.list()).items).toEqual([]);
    const inTrash = (await client.media.list({ trashed: "only" })).items;
    expect(inTrash.map((i) => i.id)).toEqual([a.id]);
    expect(inTrash[0]?.trashedAt).toEqual(expect.any(String));
    expect(adapter.mediaStore.has(a.id)).toBe(true);
    expect(adapter.deleted).toEqual([]);

    expect((await refused(client.media.restore(a.id, { expectedVersion: a.version!, changeId: "c2" }))).status).toBe(409);
    const restored = await client.media.restore(a.id, { expectedVersion: trashed.version, changeId: "c3" });
    expect(restored.version).not.toBe(trashed.version);
    expect((await client.media.list()).items.map((i) => i.id)).toEqual([a.id]);
    expect((await client.media.list({ trashed: "only" })).items).toEqual([]);
  });

  it("empties the trash for good and leaves the library alone", async () => {
    const { client, add, adapter } = setup();
    const keep = await add("keep.png");
    const a = await add("a.png");
    const b = await add("b.png");
    await client.media.trash(a.id, { expectedVersion: a.version!, changeId: "t1" });
    await client.media.trash(b.id, { expectedVersion: b.version!, changeId: "t2" });
    const result = await client.media.emptyTrash({ changeId: "empty1" });
    expect(result.changeId).toBe("empty1");
    expect([...result.deleted].sort()).toEqual([a.id, b.id].sort());
    expect(result).toMatchObject({ refused: [], more: false });
    expect([...adapter.mediaStore.keys()]).toEqual([keep.id]);
    expect([...adapter.deleted].sort()).toEqual([a.id, b.id].sort());
    expect((await client.media.emptyTrash({ changeId: "empty2" })).deleted).toEqual([]);
  });

  it("keeps a trashed file a post still uses, and names the post", async () => {
    const { client, add, adapter } = setup();
    const used = await add("used.png");
    const spare = await add("spare.png");
    await adapter.content.saveDraft("a-post", { source: `# T\n\n![x](${used.url})\n`, expectedVersion: null, changeId: "d1" });
    await client.media.trash(used.id, { expectedVersion: used.version!, changeId: "t1" });
    await client.media.trash(spare.id, { expectedVersion: spare.version!, changeId: "t2" });
    const result = await client.media.emptyTrash({ changeId: "e" });
    expect(result.deleted).toEqual([spare.id]);
    expect(result.refused).toHaveLength(1);
    expect(result.refused[0]).toMatchObject({ id: used.id, usedBy: [expect.objectContaining({ type: "post", id: "a-post" })] });
    expect(adapter.mediaStore.has(used.id)).toBe(true);
  });

  it("deletes at most 100 per request and says when more remain", async () => {
    const { client, adapter } = setup();
    for (let i = 0; i < 102; i++) {
      const f = await client.media.upload({ bytes: PNG, contentType: "image/png", filename: `f${i}.png`, changeId: `u${i}` });
      await client.media.trash(f.id, { expectedVersion: f.version!, changeId: `t${i}` });
    }
    const first = await client.media.emptyTrash({ changeId: "e1" });
    expect(first.deleted).toHaveLength(100);
    expect(first.more).toBe(true);
    const second = await client.media.emptyTrash({ changeId: "e2" });
    expect(second.more).toBe(false);
    expect(second.deleted).toHaveLength(2);
    expect(adapter.mediaStore.size).toBe(0);
  });

  it("gives each deleted file its own change id, built from the request's", async () => {
    const { client, add, adapter } = setup();
    const seen: string[] = [];
    const del = adapter.media!.delete;
    adapter.media!.delete = (id, input) => {
      seen.push(input.changeId);
      return del(id, input);
    };
    for (const name of ["a.png", "b.png"]) {
      const f = await add(name);
      await client.media.trash(f.id, { expectedVersion: f.version!, changeId: `t-${name.slice(0, 1)}` });
    }
    await client.media.emptyTrash({ changeId: "base" });
    expect(seen).toEqual(["base-1", "base-2"]);
  });
});

describe("bulk", () => {
  it("applies the op to every file and reports each file on its own", async () => {
    const { client, add, adapter } = setup();
    const a = await add("a.png");
    const b = await add("b.png");
    const result = await client.media.bulk({
      op: "trash",
      items: [
        { id: a.id, expectedVersion: a.version!, changeId: "b1" },
        { id: b.id, expectedVersion: "stale", changeId: "b2" },
        { id: "ghost.png", expectedVersion: "m1", changeId: "b3" },
        { id: a.id, changeId: "b4" },
      ],
    });
    expect(result.op).toBe("trash");
    expect(result.results).toEqual([
      { ok: true, id: a.id, changeId: "b1", version: expect.any(String) },
      { ok: false, id: b.id, changeId: "b2", error: "version-conflict", message: expect.any(String), currentVersion: b.version },
      { ok: false, id: "ghost.png", changeId: "b3", error: "not-found", message: expect.any(String) },
      { ok: false, id: a.id, changeId: "b4", error: "invalid", message: expect.any(String) },
    ]);
    expect(adapter.mediaStore.get(a.id)?.item.trashedAt).toEqual(expect.any(String));
    expect(adapter.mediaStore.get(b.id)?.item.trashedAt).toBeNull();
  });

  it("adds and removes tags from each file's current set, and refuses past 12 for that file alone", async () => {
    const { client, add, adapter } = setup();
    const a = await add("a.png");
    const b = await add("b.png");
    const a2 = await client.media.setTags(a.id, { tags: ["keep", "old"], expectedVersion: a.version!, changeId: "s1" });
    const added = await client.media.bulk({
      op: "add-tags",
      tags: ["new"],
      items: [
        { id: a.id, expectedVersion: a2.version, changeId: "b1" },
        { id: b.id, expectedVersion: b.version!, changeId: "b2" },
      ],
    });
    expect(added.results.every((r) => r.ok)).toBe(true);
    expect(adapter.mediaStore.get(a.id)?.item.tags).toEqual(["keep", "new", "old"]);
    expect(adapter.mediaStore.get(b.id)?.item.tags).toEqual(["new"]);

    const va = adapter.mediaStore.get(a.id)!.item.version!;
    const removed = await client.media.bulk({ op: "remove-tags", tags: ["old", "absent"], items: [{ id: a.id, expectedVersion: va, changeId: "b3" }] });
    expect(removed.results[0]?.ok).toBe(true);
    expect(adapter.mediaStore.get(a.id)?.item.tags).toEqual(["keep", "new"]);

    const full = await client.media.setTags(b.id, {
      tags: Array.from({ length: 12 }, (_, i) => `t${i}`),
      expectedVersion: adapter.mediaStore.get(b.id)!.item.version!,
      changeId: "s2",
    });
    const over = await client.media.bulk({
      op: "add-tags",
      tags: ["extra"],
      items: [
        { id: b.id, expectedVersion: full.version, changeId: "b4" },
        { id: a.id, expectedVersion: adapter.mediaStore.get(a.id)!.item.version!, changeId: "b5" },
      ],
    });
    expect(over.results.map((r) => r.ok)).toEqual([false, true]);
    expect(over.results[0]).toMatchObject({ error: "refused" });
    expect(adapter.mediaStore.get(b.id)?.item.tags).toHaveLength(12);
  });

  it("deletes through the site's reference check without a version, and names a refusal", async () => {
    const { client, add, adapter } = setup();
    const a = await add("a.png");
    const used = await add("used.png");
    await adapter.content.saveDraft("a-post", { source: `![x](${used.url})\n`, expectedVersion: null, changeId: "d1" });
    const result = await client.media.bulk({
      op: "delete",
      items: [
        { id: a.id, changeId: "d1" },
        { id: used.id, changeId: "d2" },
        { id: "ghost.png", changeId: "d3" },
      ],
    });
    expect(result.results.map((r) => r.ok)).toEqual([true, false, false]);
    expect(result.results[1]).toMatchObject({ error: "refused", usedBy: [expect.objectContaining({ id: "a-post" })] });
    expect(result.results[2]).toMatchObject({ error: "not-found" });
    expect(adapter.deleted).toEqual([a.id]);
    expect(adapter.mediaStore.has(used.id)).toBe(true);
  });

  it("rejects a tag op with no tags, more than 100 files and an empty list as 400, running nothing", async () => {
    const { fetch, adapter } = setup();
    const item = { id: "a.png", expectedVersion: "m1", changeId: "c" };
    const many = Array.from({ length: 101 }, (_, i) => ({ ...item, changeId: `c${i}` }));
    const payloads = [
      { op: "add-tags", items: [item] },
      { op: "add-tags", tags: [], items: [item] },
      { op: "trash", items: many },
      { op: "trash", items: [] },
      { op: "explode", items: [item] },
    ];
    for (const payload of payloads) {
      expect((await fetch(req("/api/carrel/v1/media/bulk", { method: "POST", ...body(payload) }))).status).toBe(400);
    }
    expect(adapter.mediaStore.size).toBe(0);
  });
});

describe("a site without the writes", () => {
  it("answers 501 to each route whatever the body says, and declares none of the capabilities", async () => {
    const { client, fetch, adapter } = setup({ mediaWrites: false });
    const caps = (await client.meta()).capabilities;
    expect(caps.media).toBe(true);
    expect(caps.mediaAlt ?? false).toBe(false);
    expect(caps.mediaTags ?? false).toBe(false);
    expect(caps.mediaTrash ?? false).toBe(false);
    const stale = { expectedVersion: "m1", changeId: "c" };
    const calls: Array<[string, string, unknown]> = [
      ["PUT", "alt", { alt: "x", ...stale }],
      ["PUT", "tags", { tags: ["x"], ...stale }],
      ["POST", "trash", stale],
      ["POST", "restore", stale],
    ];
    for (const [method, route, payload] of calls) {
      const response = await fetch(req(`/api/carrel/v1/media/a.png/${route}`, { method, ...body(payload) }));
      expect(response.status, route).toBe(501);
    }
    const posts: Array<[string, unknown]> = [
      ["/media/trash/empty", { changeId: "c" }],
      ["/media/bulk", { op: "trash", items: [{ id: "a.png", ...stale }] }],
      ["/media/bulk", { op: "add-tags", tags: ["x"], items: [{ id: "a.png", ...stale }] }],
    ];
    for (const [path, payload] of posts) {
      expect((await fetch(req(`/api/carrel/v1${path}`, { method: "POST", ...body(payload) }))).status, path).toBe(501);
    }
    expect(adapter.mediaStore.size).toBe(0);
  });

  it("still allows a bulk delete, which needs only the delete every media site has", async () => {
    const { client, add, adapter } = setup({ mediaWrites: false });
    const a = await add("a.png");
    expect((await client.media.bulk({ op: "delete", items: [{ id: a.id, changeId: "d" }] })).results[0]?.ok).toBe(true);
    expect(adapter.deleted).toEqual([a.id]);
  });

  it("a site with trash but no tags refuses tag ops with 501 and allows trash ops", async () => {
    const { client, add, adapter } = setup();
    delete (adapter.media as { setTags?: unknown }).setTags;
    const caps = (await client.meta()).capabilities;
    expect(caps).toMatchObject({ mediaTrash: true, mediaAlt: true });
    expect(caps.mediaTags ?? false).toBe(false);
    const f = await add("a.png");
    const input = { id: f.id, expectedVersion: f.version!, changeId: "c" };
    expect((await refused(client.media.bulk({ op: "add-tags", tags: ["x"], items: [input] }))).status).toBe(501);
    expect((await client.media.bulk({ op: "trash", items: [input] })).results[0]?.ok).toBe(true);
  });
});

